  /** The Kimai API documents no per-operation scopes — always 'unknown'. */
  permissions: string;
  pagination:
    | { mode: 'page'; vendorDefaultPageSize: number; vendorMaxPageSize: number }
    | { mode: 'none' };
  /** Helpers only: the resolution basis + bounded scan caps (null otherwise). */
  resolution: { basis: string; maxScanRecords: number; maxScanPages: number } | null;
  /** The Kimai transport does not retry; the statuses a caller may safely
   *  re-issue (none for non-idempotent mutations). No vendor idempotency
   *  pass-through. */
