  /** Stable error codes this operation can emit (plan column pass-through). */
  errors: string[];
  metadata: Record<string, unknown>;
  /** Compact summary shape name, or null. */
  compact: string | null;
  status: 'implemented' | 'tested';
  tests: Array<{ id: string; file: string; title: string }>;
